// ---- State machine: builds the ordered sequence for a given order ----
function buildSequence(order) {
  const seq = ['agreed'];
  if (order.originType === 'sourcing_order') {
    seq.push('sourcing_in_progress', 'purchase_pending');
  }
  seq.push('ready_for_handoff');
  if (order.shippingArrangement === 'handled_by_isma') {
    seq.push('in_shipping');
  }
  seq.push('delivered', 'closed');
  return seq;
}

function nextStatus(order) {
  const seq = buildSequence(order);
  const idx = seq.indexOf(order.status);
  if (idx === -1 || idx === seq.length - 1) return null;
  return seq[idx + 1];
}

