function toSnakeCase(str) { return str.replace(/[A-Z]/g, l => `_${l.toLowerCase()}`); }
function toCamelCase(str) { return str.replace(/_([a-z])/g, (_, l) => l.toUpperCase()); }
function objToSnake(o) {
  if (Array.isArray(o)) return o.map(objToSnake);
  if (o === null || typeof o !== 'object') return o;
  const out = {};
  for (const k in o) out[toSnakeCase(k)] = objToSnake(o[k]);
  return out;
}
function objToCamel(o) {
  if (Array.isArray(o)) return o.map(objToCamel);
  if (o === null || typeof o !== 'object') return o;
  const out = {};
  for (const k in o) out[toCamelCase(k)] = objToCamel(o[k]);
  return out;
}

// Real sign-in against Supabase Auth (GoTrue) — returns { access_token, user } on success.
async function supabaseSignIn(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: 'POST',
    headers: { apikey: SUPABASE_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password }),
  });
  const rawText = await res.text();
  let data = {};
  try { data = JSON.parse(rawText); } catch { /* response wasn't JSON at all */ }
  if (!res.ok) {
    const detail = data.error_description || data.msg || data.error || data.message || rawText || '(بلا تفاصيل)';
    throw new Error(`فشل الدخول [${res.status}]: ${detail}`);
  }
  return data;
}

// Generic REST call to a table, translating JS camelCase <-> SQL snake_case automatically
// so every existing handler in this app keeps using its original field names unchanged.
async function supabaseTable(table, accessToken, method = 'GET', body = null, query = '') {
  const headers = {
    apikey: SUPABASE_KEY,
    Authorization: `Bearer ${accessToken || SUPABASE_KEY}`,
    'Content-Type': 'application/json',
  };
  if (method !== 'GET') headers['Prefer'] = 'return=representation';
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}${query}`, {
    method, headers, body: body ? JSON.stringify(objToSnake(body)) : undefined,
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`${table} ${method} failed (${res.status}): ${errText}`);
  }
  if (res.status === 204) return null; // no content, e.g. some DELETEs
  const data = await res.json();
  return objToCamel(data);
}

async function loadData(key, fallback) {
  try {
    const res = await window.storage.get(key, true);
    return { value: res ? JSON.parse(res.value) : fallback, ok: true };
  } catch {
    return { value: fallback, ok: false };
  }
}
async function saveData(key, value) {
  try {
    await window.storage.set(key, JSON.stringify(value), true);
    return true;
  } catch (e) {
    console.error('storage save failed', key, e);
    return false;
  }
}

