// Cost Basis Strategy (Constitution ج.4 / v1.2): Specific cost preferred when a directly
// linked received Purchase exists; falls back to average_inventory_cost of the variant otherwise.
function getCostBasis(order, purchases, variants) {
  const linkedPurchase = purchases.find(p => p.linkedSalesOrderId === order.id && p.status === 'received');
  if (linkedPurchase) {
    if (linkedPurchase.unitCost > 0) {
      return { type: 'specific', value: linkedPurchase.unitCost };
    }
    return null; // a recorded zero/invalid cost is not a usable basis — block, don't silently report 100% margin
  }
  if (order.productVariantId) {
    const variant = variants.find(v => v.id === order.productVariantId);
    if (variant && variant.stockQuantity > 0 && variant.averageInventoryCost > 0) {
      return { type: 'average', value: variant.averageInventoryCost };
    }
  }
  return null; // closing must be blocked until a cost basis can be determined
}

// FX difference rule (ج.5): each payment already carries the rate at its own moment;
// the difference vs. the rate locked at SalesOrder agreement is the FX gain/loss.
function computeFXDifference(order, orderPayments) {
  const confirmed = orderPayments.filter(p => p.status === 'confirmed' && p.direction === 'from_client');
  let diff = 0;
  confirmed.forEach(p => {
    diff += p.amount * (p.fxRateAtPayment - order.fxRateAtAgreement);
  });
  return Math.round(diff * 100) / 100;
}

// Unified margin resolver: closed orders read the FROZEN value from the Ledger (never recomputed);
// open orders show a live projection only, clearly distinct from the final figure.
function getOrderMargin(order, purchases, variants, ledger) {
  if (order.status === 'closed') {
    const entry = ledger.find(e => e.salesOrderId === order.id && e.type === 'هامش_منتج');
    return entry ? { value: entry.amount, frozen: true, costType: entry.costBasisTypeUsed } : { value: null, frozen: true, costType: null };
  }
  const basis = getCostBasis(order, purchases, variants);
  if (!basis) return null;
  // FIXED (Critical Review finding): same per-unit-vs-total bug as the closing calculation.
  return { value: Math.round((order.agreedPrice - (basis.value * order.quantity)) * 100) / 100, frozen: false, costType: basis.type };
}

// ---- AuditLog: Append-Only by construction. This helper only ever RETURNS a new plain entry —
// it never reads or mutates existing log state, so there is no code path that can edit history. ----
let auditSeq = 0;
function makeAuditEntry(actingRole, entityType, entityId, field, oldValue, newValue) {
  auditSeq += 1;
  return {
    id: `${Date.now()}-${auditSeq}`,
    userRole: actingRole,
    entityType, entityId, field,
    oldValue: oldValue === undefined ? null : oldValue,
    newValue: newValue === undefined ? null : newValue,
    timestamp: new Date().toISOString(),
  };
}

// Lightweight count-up for numeric values only (non-numeric strings like "220 د.إ" render instantly, unchanged)
function useCountUp(value, duration = 600) {
  const [display, setDisplay] = useState(value);
  const isPureNumber = typeof value === 'number';
  useEffect(() => {
    if (!isPureNumber) { setDisplay(value); return; }
    let raf;
    const start = performance.now();
    const from = 0;
    const to = value;
    const tick = (now) => {
      const progress = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - progress, 3);
      setDisplay(Math.round(from + (to - from) * eased));
      if (progress < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [value, isPureNumber, duration]);
  return isPureNumber ? display : value;
}

function AnimatedValue({ value }) {
  let num = 0, suffix = '', isNumeric = false;
  if (typeof value === 'number') {
    num = value; isNumeric = true;
  } else if (typeof value === 'string') {
    const match = value.match(/^(-?\d+(?:\.\d+)?)(.*)$/);
    if (match) { num = parseFloat(match[1]); suffix = match[2]; isNumeric = true; }
  }
  const display = useCountUp(isNumeric ? num : 0, 600);
  if (!isNumeric) return <>{value}</>;
  return <>{display}{suffix}</>;
}

