function SettingsView({ categories, onAddCategory, onRemoveCategory, variants, role, assistantCanPurchase }) {
  const [newCat, setNewCat] = useState('');

  const categoryInUse = (cat) => variants.some(v => v.category === cat);

  return (
    <div className="space-y-5 max-w-2xl">
      <div className="isma-card bg-[#FDF8ED] rounded-2xl border border-stone-200/70 p-5">
        <h4 className="text-xs font-semibold text-stone-500 uppercase tracking-wide flex items-center gap-1.5 border-s-2 border-[#FBBF24]/50 ps-2 mb-4">
          <Store size={13} className="opacity-70" /> فئات المنتجات
        </h4>
        <div className="flex flex-wrap gap-2 mb-4">
          {categories.map(cat => (
            <span key={cat} className="flex items-center gap-1.5 text-sm bg-white rounded-full px-3 py-1.5 border border-stone-200">
              {cat}
              {!categoryInUse(cat) && (
                <button onClick={() => onRemoveCategory(cat)} className="text-stone-400 hover:text-[#B24444] transition-colors">
                  <X size={12} />
                </button>
              )}
            </span>
          ))}
          {!categories.length && <div className="text-xs text-stone-400">لا توجد فئات بعد</div>}
        </div>
        <div className="flex gap-2">
          <input value={newCat} onChange={e => setNewCat(e.target.value)} placeholder="فئة جديدة (مثال: عطور)"
            className="flex-1 px-3 py-2 rounded-lg border border-stone-300 text-sm transition-colors focus:border-[#D97706] focus:outline-none" />
          <button onClick={() => { if (newCat.trim()) { onAddCategory(newCat.trim()); setNewCat(''); } }}
            className="bg-[#D97706] text-white px-4 py-2 rounded-lg text-sm hover:brightness-105 active:scale-[0.98] transition-all">إضافة</button>
        </div>
      </div>

      {role === 'owner' && (
        <div className="isma-card bg-[#FDF8ED] rounded-2xl border border-stone-200/70 p-5">
          <h4 className="text-xs font-semibold text-stone-500 uppercase tracking-wide flex items-center gap-1.5 border-s-2 border-[#FBBF24]/50 ps-2 mb-4">
            <ShieldCheck size={13} className="opacity-70" /> الصلاحيات الحالية
          </h4>
          <div className="text-sm space-y-2">
            <div className="flex justify-between"><span className="text-stone-500">الدور الحالي</span><span className="font-medium">Owner</span></div>
            <div className="flex justify-between"><span className="text-stone-500">صلاحية Assistant للشراء</span><span className="font-medium">{assistantCanPurchase ? 'مفعَّلة' : 'غير مفعَّلة'}</span></div>
          </div>
          <div className="text-[11px] text-stone-400 mt-3 pt-3 border-t border-stone-100">
            تُدار هذه الصلاحية من زر التبديل أسفل القائمة الجانبية — للتجربة فقط، بانتظار نظام مصادقة حقيقي.
          </div>
        </div>
      )}
    </div>
  );
}

function PaymentsView({ payments, orders, purchases, clients, suppliers, role }) {
  const [directionFilter, setDirectionFilter] = useState('all');
  const [search, setSearch] = useState('');

  const rows = payments.map(p => {
    if (p.direction === 'from_client') {
      const order = orders.find(o => o.id === p.salesOrderId);
      const client = order ? clients.find(c => c.id === order.clientId) : null;
      return { ...p, party: client?.name || '—', context: order ? `طلب #${order.id}` : '—' };
    }
    const purchase = purchases.find(pu => pu.id === p.purchaseId);
    const supplier = purchase ? suppliers.find(s => s.id === purchase.supplierId) : null;
    return { ...p, party: supplier?.name || '—', context: purchase ? `شراء #${purchase.id}` : '—' };
  }).sort((a, b) => (a.date < b.date ? 1 : -1));

  const filtered = rows.filter(r => {
    const matchesDir = directionFilter === 'all' || r.direction === directionFilter;
    const q = search.trim().toLowerCase();
    const matchesSearch = !q || r.party.toLowerCase().includes(q);
    return matchesDir && matchesSearch;
  });

  const totalIn = rows.filter(r => r.direction === 'from_client' && r.status === 'confirmed').reduce((s, r) => s + r.amount, 0);
  const totalOut = rows.filter(r => r.direction === 'to_supplier' && r.status === 'confirmed').reduce((s, r) => s + r.amount, 0);

  if (role !== 'owner') {
    return (
      <div className="isma-card bg-[#FDF8ED] rounded-2xl border border-stone-200/70 p-10 text-center text-stone-400 text-sm">
        <Lock size={24} className="mx-auto mb-2 opacity-40" />
        السجل الكامل للدفعات متاح لـOwner فقط
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-3 sm:gap-4">
        <KPICard label="مقبوضات من العملاء (مؤكَّدة)" value={`${totalIn} د.إ`} color={MODULE_COLORS.orders} />
        <KPICard label="مدفوعات للموردين (مؤكَّدة)" value={`${totalOut} د.إ`} color={MODULE_COLORS.purchases} />
      </div>

      <div className="flex flex-wrap gap-2">
        <div className="relative">
          <Search size={15} className="absolute start-3 top-1/2 -translate-y-1/2 text-stone-400" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="بحث بالاسم..."
            className="ps-8 pe-3 py-2 rounded-lg border border-stone-300 text-sm w-full sm:w-56 transition-colors focus:border-[#D97706] focus:outline-none" />
        </div>
        <select value={directionFilter} onChange={e => setDirectionFilter(e.target.value)}
          className="px-3 py-2 rounded-lg border border-stone-300 text-sm bg-[#FDF8ED] transition-colors focus:border-[#D97706] focus:outline-none">
          <option value="all">كل الاتجاهات</option>
          <option value="from_client">من العملاء</option>
          <option value="to_supplier">للموردين</option>
        </select>
      </div>

      <div className="isma-card bg-[#FDF8ED] rounded-2xl border border-stone-200/70 overflow-x-auto transition-shadow duration-200">
        <table className="w-full text-sm min-w-[560px]">
          <thead className="bg-[#F3EDE0]/70 text-[#8A7A5A] text-[11px] uppercase tracking-wide">
            <tr>
              <th className="text-start p-3 font-medium">التاريخ</th>
              <th className="text-start p-3 font-medium">الطرف</th>
              <th className="text-start p-3 font-medium">السياق</th>
              <th className="text-start p-3 font-medium">الاتجاه</th>
              <th className="text-start p-3 font-medium">الحالة</th>
              <th className="text-start p-3 font-medium">المبلغ</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map(r => (
              <tr key={r.id} className="border-t border-stone-100">
                <td className="p-3 text-stone-500">{r.date}</td>
                <td className="p-3 font-medium text-stone-800">{r.party}</td>
                <td className="p-3 text-stone-500">{r.context}</td>
                <td className="p-3">
                  <span className={`text-xs px-2 py-0.5 rounded-full text-white ${r.direction === 'from_client' ? 'bg-[#F97316]' : 'bg-[#D97706]'}`}>
                    {r.direction === 'from_client' ? 'من عميل' : 'لمورد'}
                  </span>
                </td>
                <td className="p-3">
                  <span className={`text-[10px] px-2 py-0.5 rounded-full ${r.status === 'confirmed' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                    {r.status === 'confirmed' ? 'مؤكَّدة' : 'معلَّقة'}
                  </span>
                </td>
                <td className={`p-3 font-medium ${r.direction === 'from_client' ? 'text-[#059669]' : 'text-[#B24444]'}`}>
                  {r.direction === 'from_client' ? '+' : '-'}{r.amount} {r.currency}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {!filtered.length && (
          <div className="p-10 text-center text-stone-400 text-sm">
            <div className="flex justify-center mb-2 opacity-40"><CreditCard size={28} strokeWidth={1.5} /></div>
            لا توجد دفعات مطابقة
          </div>
        )}
      </div>
    </div>
  );
}

// ============== CUSTOMER-FACING CATALOG (same app, same state — genuinely shares data with admin) ==============

function CustomerOrderModal({ variant, onClose, onConfirm }) {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [city, setCity] = useState('');
  const [size, setSize] = useState('M');
  const [color, setColor] = useState('');
  const [qty, setQty] = useState(1);
  const price = variant.sellingPrice || 0;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-end sm:items-center justify-center z-50">
      <div className="bg-[#FBF6EA] rounded-t-3xl sm:rounded-3xl w-full sm:max-w-md max-h-[92vh] overflow-y-auto shadow-2xl">
        {/* Header band */}
        <div className="relative px-5 pt-5 pb-4 text-center border-b border-[#FBBF24]/25">
          <button onClick={onClose} className="absolute left-4 top-4 text-stone-400"><X size={20} /></button>
          <div className="w-9 h-9 rounded-full border-2 border-[#D97706] mx-auto mb-2 flex items-center justify-center">
            <img src={ISMA_LOGO} alt="" className="w-6 h-6 object-contain" />
          </div>
          <h3 className="font-display text-lg text-[#153630]">{variant.name}</h3>
          <div className="text-[11px] text-[#92400E] mt-0.5">تأكيد الطلب</div>
        </div>

        {/* Trust feature pills — icon-badge + label, matching the reference ad's feature row */}
        <div className="flex justify-center gap-3 px-5 py-4">
          {[
            { icon: CheckCircle2, label: 'جودة موثوقة' },
            { icon: Truck, label: 'شحن آمن' },
            { icon: ShieldCheck, label: 'تحقق قبل الشراء' },
          ].map((f, i) => (
            <div key={i} className="flex flex-col items-center gap-1.5">
              <div className="w-11 h-11 rounded-full border-2 border-[#FBBF24]/50 flex items-center justify-center bg-white">
                <f.icon size={17} className="text-[#D97706]" />
              </div>
              <span className="text-[10px] text-stone-600 text-center max-w-[64px] leading-tight">{f.label}</span>
            </div>
          ))}
        </div>

        <div className="px-5 pb-5 space-y-3">
          <input value={name} onChange={e => setName(e.target.value)} placeholder="الاسم الكامل"
            className="w-full px-3 py-2.5 rounded-xl border border-stone-300 text-sm focus:border-[#D97706] focus:outline-none" />
          <input value={phone} onChange={e => setPhone(e.target.value)} placeholder="رقم الهاتف / واتساب"
            className="w-full px-3 py-2.5 rounded-xl border border-stone-300 text-sm focus:border-[#D97706] focus:outline-none" />
          <input value={city} onChange={e => setCity(e.target.value)} placeholder="المدينة"
            className="w-full px-3 py-2.5 rounded-xl border border-stone-300 text-sm focus:border-[#D97706] focus:outline-none" />
          <div className="grid grid-cols-2 gap-2">
            <select value={size} onChange={e => setSize(e.target.value)} className="px-3 py-2.5 rounded-xl border border-stone-300 text-sm bg-white">
              {['XS', 'S', 'M', 'L', 'XL', 'XXL', 'مقاس خاص'].map(s => <option key={s} value={s}>{s}</option>)}
            </select>
            <input value={color} onChange={e => setColor(e.target.value)} placeholder="اللون"
              className="px-3 py-2.5 rounded-xl border border-stone-300 text-sm focus:border-[#D97706] focus:outline-none" />
          </div>
          <div className="flex items-center justify-between bg-white rounded-xl border border-stone-300 px-3 py-2">
            <span className="text-sm text-stone-500">الكمية</span>
            <div className="flex items-center gap-3">
              <button onClick={() => setQty(q => Math.max(1, q - 1))} className="w-7 h-7 rounded-md border border-stone-300 text-sm">−</button>
              <span className="text-sm font-medium w-5 text-center">{qty}</span>
              <button onClick={() => setQty(q => q + 1)} className="w-7 h-7 rounded-md border border-stone-300 text-sm">+</button>
            </div>
          </div>

          {/* Bold price hero box — the focal element, matching the reference ad's oversized pricing */}
          <div className="rounded-2xl p-4 text-center" style={{ background: 'linear-gradient(135deg, #E9C989, #D97706)' }}>
            <div className="text-[11px] text-white/85 mb-1">السعر الإجمالي التقديري</div>
            <div className="font-display text-4xl text-white leading-none">{price * qty}<span className="text-lg align-top ms-1">د.إ</span></div>
          </div>

          <button
            onClick={() => { if (name.trim() && phone.trim()) onConfirm({ name: name.trim(), phone: phone.trim(), city, size, color, qty, price: price * qty }); }}
            className="isma-shine-btn w-full bg-[#25D366] text-white py-3.5 rounded-full text-sm font-semibold hover:brightness-105 active:scale-[0.98] transition-all flex items-center justify-center gap-2 shadow-lg">
            <Send size={16} /> تأكيد وإرسال الطلب
          </button>
          <div className="text-[11px] text-stone-400 text-center">سنتواصل معك عبر واتساب لتأكيد التفاصيل والسعر النهائي قبل أي دفع</div>
        </div>
      </div>
    </div>
  );
}

const CATEGORY_DESCRIPTIONS = {
  'عبايات': 'قطعة مُنتقاة بعناية من أفضل موردي الخليج — قماش عالي الجودة وتفصيل أنيق يناسب الإطلالة اليومية والمناسبات.',
  'أطقم مطرزة': 'طقم متكامل (قماش مطبوع + شيلة مطرزة متناسقة) بتطريز دقيق وألوان ثابتة — جاهز للتفصيل حسب مقاسك.',
};

function ProductDetailView({ product, onClose, onOrder }) {
  const img = product.images && product.images[0];
  const desc = CATEGORY_DESCRIPTIONS[product.category] || 'قطعة مُنتقاة بعناية من مورد موثوق فالخليج.';
  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center">
      <div className="bg-[#FBF6EA] rounded-t-3xl sm:rounded-3xl w-full sm:max-w-lg max-h-[92vh] overflow-y-auto">
        <div className="relative">
          <button onClick={onClose} className="absolute top-3 left-3 z-10 w-8 h-8 rounded-full bg-black/40 text-white flex items-center justify-center"><X size={16} /></button>
          <div className="aspect-square bg-gradient-to-br from-[#EDE5D6] to-[#DCCFB4]">
            {img ? <img src={img} alt={product.name} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center"><Package size={48} className="text-[#153630]/25" /></div>}
          </div>
        </div>
        <div className="p-5">
          <h2 className="font-display text-xl text-[#153630] mb-1">{product.name}</h2>
          <div className="text-xs text-stone-500 mb-3">{product.category}</div>
          <div className="rounded-xl p-3 mb-4 text-center" style={{ background: 'linear-gradient(135deg, #EFD9AE, #C99A4E)' }}>
            <span className="font-display text-2xl text-white">{product.sellingPrice || 0}<span className="text-sm align-top ms-1">د.إ</span></span>
          </div>
          <p className="text-sm text-stone-600 mb-4 leading-relaxed">{desc}</p>

          <div className="grid grid-cols-3 gap-2 mb-5">
            {[{ icon: ShieldCheck, label: 'تحقق شخصي قبل الشحن' }, { icon: Truck, label: 'شحن متابَع' }, { icon: CheckCircle2, label: 'ضمان مطابقة الوصف' }].map((t, i) => (
              <div key={i} className="flex flex-col items-center gap-1 text-center bg-white rounded-xl p-2 border border-stone-200">
                <t.icon size={18} className="text-[#0D9488]" />
                <span className="text-[10px] text-stone-600">{t.label}</span>
              </div>
            ))}
          </div>

          <button onClick={() => onOrder(product)} disabled={product.stockQuantity <= 0}
            className="isma-shine-btn w-full bg-[#0D9488] text-white py-3 rounded-full text-sm font-semibold disabled:opacity-40">
            {product.stockQuantity <= 0 ? 'نفدت الكمية' : 'اطلب الآن'}
          </button>
          <div className="text-[11px] text-stone-400 text-center mt-2">السعر يشمل التحقق والتغليف — التواصل والتأكيد عبر واتساب قبل أي دفع</div>
        </div>
      </div>
    </div>
  );
}

function CustomerCatalog({ variants, clients, orders, setClients, setOrders, onSwitchToAdmin }) {
  const [category, setCategory] = useState('all');
  const [search, setSearch] = useState('');
  const [selected, setSelected] = useState(null);
  const [detailProduct, setDetailProduct] = useState(null);
  const [confirmed, setConfirmed] = useState(false);
  const topRef = useRef(null);
  const categoriesRef = useRef(null);
  const searchInputRef = useRef(null);

  const handleConfirmOrder = useCallback(async (form) => {
    let client = clients.find(c => c.phone === form.phone);
    let updatedClients = clients;
    if (!client) {
      client = { id: Date.now(), name: form.name, phone: form.phone, city: form.city, status: 'active', notes: '' };
      updatedClients = [...clients, client];
      setClients(updatedClients);
    }
    const newOrder = {
      id: Date.now() + 1, clientId: client.id,
      productName: `${selected.name} (${form.size}${form.color ? '، ' + form.color : ''})`,
      productVariantId: selected.id, quantity: form.qty, agreedPrice: form.price, currency: 'AED', fxRateAtAgreement: 1,
      originType: 'storefront_sale', shippingArrangement: 'handled_by_isma', status: 'agreed',
      notes: `طلب من الكاتالوج العام — مقاس: ${form.size}${form.color ? '، لون: ' + form.color : ''}`,
      createdAt: new Date().toISOString().slice(0, 10),
    };
    setOrders([...orders, newOrder]);
    setSelected(null);
    setConfirmed(true);
    setTimeout(() => setConfirmed(false), 4000);
  }, [clients, orders, selected, setClients, setOrders]);

  const categories = ['all', ...Array.from(new Set(variants.map(v => v.category).filter(Boolean)))];
  const filtered = variants.filter(v => {
    const matchesCat = category === 'all' || v.category === category;
    const matchesSearch = !search.trim() || v.name.toLowerCase().includes(search.trim().toLowerCase());
    return matchesCat && matchesSearch;
  });

  const scrollToRef = (ref) => ref.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });

  return (
    <div dir="rtl" className="min-h-screen bg-[#F7F2E7] pb-20" style={{ fontFamily: "'Tajawal', 'Inter', sans-serif" }}>
      <style>{`
        @keyframes isma-mesh-breathe {
          0%, 100% { transform: scale(1) translate(0, 0); opacity: 0.55; }
          50% { transform: scale(1.15) translate(2%, -2%); opacity: 0.8; }
        }
        @keyframes isma-twinkle {
          0%, 100% { opacity: 0.15; }
          50% { opacity: 1; }
        }
        @keyframes isma-shimmer {
          0% { background-position: -200% center; }
          100% { background-position: 200% center; }
        }
        @keyframes isma-shine {
          0% { transform: translateX(-120%) skewX(-20deg); }
          100% { transform: translateX(220%) skewX(-20deg); }
        }
        .isma-mesh { animation: isma-mesh-breathe 7s ease-in-out infinite; }
        .isma-star { animation: isma-twinkle 2.4s ease-in-out infinite; }
        .isma-shimmer-text {
          background: linear-gradient(90deg, #FBBF24 0%, #FFF6D6 25%, #FBBF24 50%, #FFF6D6 75%, #FBBF24 100%);
          background-size: 200% auto;
          -webkit-background-clip: text; background-clip: text; color: transparent;
          animation: isma-shimmer 3.5s linear infinite;
        }
        .isma-shine-btn { position: relative; overflow: hidden; }
        .isma-shine-btn::after {
          content: ''; position: absolute; top: 0; bottom: 0; left: 0; width: 40%;
          background: linear-gradient(110deg, transparent, rgba(255,255,255,0.45), transparent);
          animation: isma-shine 3.2s ease-in-out infinite; animation-delay: 1s;
        }
        .isma-glass { background: rgba(255,255,255,0.55); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); border: 1px solid rgba(255,255,255,0.6); }
        .isma-glass-dark { background: rgba(13,148,136,0.25); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); border: 1px solid rgba(255,255,255,0.15); }
      `}</style>

      <div ref={topRef} />

      {/* Simplified header */}
      <header className="isma-glass-dark text-white px-4 py-3 sticky top-0 z-30">
        <div className="max-w-3xl mx-auto flex items-center justify-between">
          <button onClick={onSwitchToAdmin} className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-white/10 transition-colors">
            <Menu size={18} />
          </button>
          <div className="font-display text-lg">ISMA</div>
          <div className="w-8 h-8 rounded-full overflow-hidden bg-white/90 flex items-center justify-center">
            <img src={ISMA_LOGO} alt="" className="w-5 h-5 object-contain" />
          </div>
        </div>
      </header>

      {/* Hero — animated gradient mesh + twinkling stars + shimmer title */}
      <div className="relative text-center px-4 pt-10 pb-16 overflow-hidden" style={{ background: 'linear-gradient(180deg, #0B1F1C 0%, #0F2C27 55%, #153630 100%)' }}>
        <div className="isma-mesh absolute inset-0" style={{ background: 'radial-gradient(circle at 30% 20%, rgba(251,191,36,0.35), transparent 55%), radial-gradient(circle at 75% 60%, rgba(13,148,136,0.4), transparent 50%)' }} />
        <div className="absolute inset-0 opacity-70">
          {[[20, 20], [70, 15], [40, 35], [85, 30], [55, 10], [15, 45], [90, 50], [60, 22]].map(([x, y], i) => (
            <span key={i} className="isma-star absolute rounded-full bg-[#FBBF24]" style={{ left: `${x}%`, top: `${y}%`, width: i % 2 ? 2 : 1.5, height: i % 2 ? 2 : 1.5, animationDelay: `${i * 0.35}s` }} />
          ))}
        </div>
        <svg viewBox="0 0 400 90" className="absolute bottom-0 inset-x-0 w-full opacity-80" preserveAspectRatio="none">
          <path d="M0,90 L0,60 L20,60 L20,45 L35,45 L35,55 L50,55 L50,30 L58,30 L58,90 Z
                   M70,90 L70,50 L85,50 L85,20 L92,10 L99,20 L99,50 L114,50 L114,90 Z
                   M130,90 L130,65 L145,65 L145,40 L160,40 L160,65 L175,65 L175,90 Z
                   M190,90 L190,55 L200,55 L200,5 L206,5 L206,55 L216,55 L216,90 Z
                   M230,90 L230,48 L248,48 L248,25 L260,25 L260,48 L278,48 L278,90 Z
                   M290,90 L290,60 L305,60 L305,42 L320,42 L320,60 L335,60 L335,90 Z
                   M350,90 L350,55 L365,55 L365,35 L378,35 L378,55 L392,55 L392,90 L400,90 Z"
            fill="#0B1F1C" />
        </svg>

        <div className="relative">
          <div className="w-16 h-16 rounded-full border-2 border-[#FBBF24] mx-auto mb-3 flex items-center justify-center bg-white/95 shadow-[0_0_25px_rgba(251,191,36,0.35)]">
            <img src={ISMA_LOGO} alt="ISMA" className="w-11 h-11 object-contain" />
          </div>
          <h1 className="font-display text-3xl mb-1 isma-shimmer-text font-semibold">ISMA</h1>
          <p className="text-xs mb-2" style={{ color: '#FBBF24' }}>مختارات مُنتقاة بعناية، مباشرة من الخليج</p>
        </div>
      </div>

      {/* Floating glassmorphism search card, overlapping the hero edge */}
      <div className="max-w-3xl mx-auto px-4 -mt-8 relative z-10">
        <div className="isma-glass rounded-2xl p-4 shadow-xl">
          <div className="relative mb-3">
            <Search size={16} className="absolute start-3 top-1/2 -translate-y-1/2 text-[#153630]/50" />
            <input ref={searchInputRef} value={search} onChange={e => setSearch(e.target.value)} placeholder="ابحث عن منتج..."
              className="w-full ps-9 pe-3 py-2.5 rounded-xl border border-white/60 bg-white/80 text-sm focus:border-[#0D9488] focus:outline-none" />
          </div>
          <div ref={categoriesRef} className="flex gap-2 overflow-x-auto pb-1">
            {categories.map(cat => (
              <button key={cat} onClick={() => setCategory(cat)}
                className={`px-4 py-1.5 rounded-full text-xs whitespace-nowrap transition-colors ${category === cat ? 'bg-[#0D9488] text-white' : 'bg-white/70 text-stone-600'}`}>
                {cat === 'all' ? 'الكل' : cat}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="max-w-3xl mx-auto px-4 pt-5 pb-5">
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {filtered.map(v => {
            const soldOut = v.stockQuantity <= 0;
            const img = v.images && v.images[0];
            return (
              <div key={v.id} className={`bg-white rounded-2xl border border-stone-200/70 overflow-hidden shadow-sm ${soldOut ? 'opacity-50' : ''}`}>
                <button onClick={() => setDetailProduct(v)} className="w-full block">
                  <div className="aspect-square bg-gradient-to-br from-[#EDE5D6] to-[#DCCFB4] flex items-center justify-center relative overflow-hidden">
                    {img ? <img src={img} alt={v.name} className="w-full h-full object-cover" /> : <Package size={32} className="text-[#153630]/25" />}
                    {soldOut && <span className="absolute top-2 inset-x-2 bg-[#B24444] text-white text-[10px] text-center py-1 rounded-md">نفدت الكمية</span>}
                    {!soldOut && v.stockQuantity <= 3 && <span className="absolute top-2 inset-x-2 bg-[#D97706] text-white text-[10px] text-center py-1 rounded-md">كمية محدودة: {v.stockQuantity}</span>}
                  </div>
                </button>
                <div className="p-3">
                  <button onClick={() => setDetailProduct(v)} className="w-full text-start">
                    <div className="text-sm font-medium text-stone-800 mb-1 line-clamp-1">{v.name}</div>
                    <div className="text-xs text-stone-500 mb-2.5">{v.category}</div>
                  </button>
                  <div className="rounded-lg p-2 mb-2.5 text-center" style={{ background: 'linear-gradient(135deg, #EFD9AE, #C99A4E)' }}>
                    <span className="font-display text-lg text-white">{v.sellingPrice || 0}<span className="text-[10px] align-top ms-0.5">د.إ</span></span>
                  </div>
                  <button disabled={soldOut} onClick={() => setSelected(v)}
                    className="isma-shine-btn w-full text-xs bg-[#0D9488] text-white px-3 py-2.5 rounded-full disabled:opacity-40 hover:brightness-110 active:scale-[0.97] transition-all font-medium">
                    اطلب الآن
                  </button>
                </div>
              </div>
            );
          })}
        </div>
        {!filtered.length && (
          <div className="text-center text-stone-400 text-sm py-16">
            {variants.length === 0 ? 'لا توجد منتجات فالكاتالوج بعد' : 'لا توجد نتائج مطابقة'}
          </div>
        )}
      </div>

      {selected && <CustomerOrderModal variant={selected} onClose={() => setSelected(null)} onConfirm={handleConfirmOrder} />}
      {detailProduct && (
        <ProductDetailView product={detailProduct} onClose={() => setDetailProduct(null)}
          onOrder={(p) => { setDetailProduct(null); setSelected(p); }} />
      )}

      {confirmed && (
        <div className="fixed bottom-24 inset-x-0 flex justify-center z-50 px-4">
          <div className="flex items-center gap-2 bg-[#0D9488] text-white text-sm px-4 py-3 rounded-xl shadow-2xl">
            <CheckCircle2 size={16} className="text-[#7FCBA4]" />
            تم إرسال طلبك! سنتواصل معك قريباً لتأكيد التفاصيل.
          </div>
        </div>
      )}

      {/* Glass bottom navigation */}
      <nav className="fixed bottom-0 inset-x-0 isma-glass-dark z-40 px-2 py-2" style={{ background: 'rgba(21,54,48,0.85)' }}>
        <div className="max-w-3xl mx-auto grid grid-cols-4 gap-1">
          {[
            { icon: Home, label: 'الرئيسية', action: () => scrollToRef(topRef) },
            { icon: Store, label: 'الفئات', action: () => scrollToRef(categoriesRef) },
            { icon: Search, label: 'بحث', action: () => searchInputRef.current?.focus() },
            { icon: ShieldCheck, label: 'الإدارة', action: onSwitchToAdmin },
          ].map((item, i) => (
            <button key={i} onClick={item.action} className="flex flex-col items-center gap-0.5 py-1.5 rounded-xl text-white/85 hover:text-white hover:bg-white/10 transition-colors">
              <item.icon size={18} />
              <span className="text-[10px]">{item.label}</span>
            </button>
          ))}
        </div>
      </nav>
    </div>
  );
}

function FinancialLedgerView({ ledger, orders, clients }) {
  const [typeFilter, setTypeFilter] = useState('all');

  const filtered = typeFilter === 'all' ? ledger : ledger.filter(e => e.type === typeFilter);
  const sorted = [...filtered].sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));

  const orderLabel = (id) => {
    const o = orders.find(x => x.id === id);
    if (!o) return '—';
    const c = clients.find(x => x.id === o.clientId);
    return `#${o.id} — ${c?.name || ''}`;
  };

  const totals = ['هامش_منتج', 'Shipping Cost / Shipping Transaction', 'فرق_صرف'].map(t => {
    const byCurrency = ledger.filter(e => e.type === t)
      .reduce((acc, e) => { const cur = e.currency || 'AED'; acc[cur] = (acc[cur] || 0) + e.amount; return acc; }, {});
    const currencies = Object.keys(byCurrency);
    const display = currencies.length ? currencies.map(cur => `${byCurrency[cur]} ${cur}`).join(' + ') : '0 د.إ';
    return { type: t, display };
  });

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        {totals.map(t => (
          <KPICard key={t.type} label={LEDGER_TYPE_LABELS[t.type]} value={t.display} color={MODULE_COLORS.ledger} />
        ))}
      </div>

      <select value={typeFilter} onChange={e => setTypeFilter(e.target.value)} className="px-3 py-2 rounded-lg border border-stone-300 text-sm bg-[#FDF8ED] transition-colors focus:border-[#D97706] focus:outline-none">
        <option value="all">كل الأنواع</option>
        {Object.entries(LEDGER_TYPE_LABELS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
      </select>

      <div className="isma-card bg-[#FDF8ED] rounded-2xl border border-stone-200/70 overflow-x-auto transition-shadow duration-200">
        <table className="w-full text-sm min-w-[560px]">
          <thead className="bg-[#059669] text-white text-[11px] uppercase tracking-wide">
            <tr>
              <th className="text-start p-3 font-medium">التاريخ</th>
              <th className="text-start p-3 font-medium">النوع</th>
              <th className="text-start p-3 font-medium">الطلب</th>
              <th className="text-start p-3 font-medium">أساس التكلفة</th>
              <th className="text-start p-3 font-medium">المبلغ</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map(e => (
              <tr key={e.id} className="border-t border-stone-100">
                <td className="p-3 text-stone-500">{e.createdAt}</td>
                <td className="p-3 text-stone-700">{LEDGER_TYPE_LABELS[e.type]}</td>
                <td className="p-3 text-stone-600">{e.salesOrderId ? orderLabel(e.salesOrderId) : '—'}</td>
                <td className="p-3 text-stone-500 text-xs">{e.costBasisTypeUsed === 'specific' ? `شراء مرتبط (${e.costValueUsed})` : e.costBasisTypeUsed === 'average' ? `متوسط مخزون (${e.costValueUsed})` : '—'}</td>
                <td className={`p-3 font-medium ${e.amount >= 0 ? 'text-[#059669]' : 'text-[#B24444]'}`}>{e.amount} د.إ</td>
              </tr>
            ))}
          </tbody>
        </table>
        {!sorted.length && <div className="p-10 text-center text-stone-400 text-sm">
          <div className="flex justify-center mb-2 opacity-40"><Wallet size={28} strokeWidth={1.5} /></div>
          لا توجد قيود بعد — تُنشأ تلقائياً عند إغلاق الطلبات ماليًا
        </div>}
      </div>
      <div className="text-xs text-stone-400 flex items-start gap-1"><Lock size={12} className="mt-0.5 shrink-0" /><span>هذا السجل Append-Only — لا يمكن تعديل أي قيد بعد إنشائه، أي تصحيح يظهر كقيد "تصحيح" منفصل.</span></div>
    </div>
  );
}

function ProductCard({ variant, categories, onSave }) {
  const [editing, setEditing] = useState(false);
  const [name, setName] = useState(variant.name);
  const [category, setCategory] = useState(variant.category);
  const [price, setPrice] = useState(variant.sellingPrice);
  const [showLightbox, setShowLightbox] = useState(false);
  const isDraft = !variant.sellingPrice || variant.sellingPrice <= 0;

  const save = () => {
    onSave(variant.id, { name: name.trim() || variant.name, category, sellingPrice: parseFloat(price) || 0 });
    setEditing(false);
  };

  return (
    <div className={`bg-white rounded-xl border ${isDraft ? 'border-[#7C3AED]/40' : 'border-stone-200'} overflow-hidden`}>
      <div className="aspect-square bg-stone-100 relative">
        {variant.images?.[0]
          ? <img src={variant.images[0]} alt={variant.name} onClick={() => setShowLightbox(true)}
              className="w-full h-full object-cover cursor-zoom-in" />
          : <div className="w-full h-full flex items-center justify-center text-stone-300"><PackageSearch size={28} /></div>}
        {isDraft && <span className="absolute top-1.5 start-1.5 bg-[#7C3AED] text-white text-[10px] px-1.5 py-0.5 rounded-full">مسودة — كمّل التفاصيل</span>}
      </div>
      {showLightbox && variant.images?.[0] && (
        <div onClick={() => setShowLightbox(false)}
          className="fixed inset-0 bg-black/85 z-[100] flex items-center justify-center p-4 cursor-zoom-out">
          <button onClick={() => setShowLightbox(false)}
            className="absolute top-4 end-4 text-white bg-white/10 rounded-full p-2"><X size={22} /></button>
          <img src={variant.images[0]} alt={variant.name} onClick={e => e.stopPropagation()}
            className="max-w-[92vw] max-h-[88vh] object-contain rounded-lg" />
        </div>
      )}
      <div className="p-2.5 space-y-1.5">
        {editing ? (
          <>
            <input value={name} onChange={e => setName(e.target.value)} className="w-full px-2 py-1 rounded-md border border-stone-300 text-xs" placeholder="اسم المنتج" />
            <select value={category} onChange={e => setCategory(e.target.value)} className="w-full px-2 py-1 rounded-md border border-stone-300 text-xs bg-white">
              <option value="">بدون فئة</option>
              {categories.filter(c => c !== 'all').map(c => <option key={c} value={c}>{c}</option>)}
            </select>
            <input type="number" value={price} onChange={e => setPrice(e.target.value)} placeholder="السعر" className="w-full px-2 py-1 rounded-md border border-stone-300 text-xs" />
            <div className="flex gap-1.5">
              <button onClick={save} className="flex-1 bg-[#7C3AED] text-white py-1 rounded-md text-xs">حفظ</button>
              <button onClick={() => setEditing(false)} className="px-2 py-1 rounded-md border border-stone-300 text-xs">إلغاء</button>
            </div>
          </>
        ) : (
          <>
            <div className="text-xs font-medium text-[#153630] truncate">{variant.name}</div>
            <div className="text-[11px] text-stone-500">{variant.category || 'بدون فئة'}</div>
            <div className="text-xs font-semibold text-[#7C3AED]">{variant.sellingPrice ? `${variant.sellingPrice} AED` : 'بلا سعر'}</div>
            <button onClick={() => setEditing(true)} className="w-full mt-1 border border-[#7C3AED]/40 text-[#7C3AED] py-1 rounded-md text-[11px]">تعديل</button>
          </>
        )}
      </div>
    </div>
  );
}

function ProductsManager({ variants, categories, onCreateVariant, onUpdateVariant }) {
  const [bulkCategory, setBulkCategory] = useState(categories.find(c => c !== 'all') || '');
  const fileInputRef = useRef(null);

  const handleBulkFiles = (e) => {
    const files = Array.from(e.target.files || []);
    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = () => {
        const name = nextSequentialName(bulkCategory, variants);
        onCreateVariant({ name, category: bulkCategory, sellingPrice: 0, currency: 'AED', images: [reader.result] });
      };
      reader.readAsDataURL(file);
    });
    e.target.value = '';
  };

  const draftCount = variants.filter(v => !v.sellingPrice || v.sellingPrice <= 0).length;

  return (
    <div>
      <div className="bg-white rounded-xl border border-stone-200 p-4 mb-5">
        <h3 className="font-display text-base text-[#153630] mb-2.5">رفع صور بالجملة</h3>
        <p className="text-xs text-stone-500 mb-3">اختار الفئة مرة وحدة، بعدها اختار كل الصور دفعة واحدة — كل صورة غادي تولّي منتج "مسودة" بلا سعر، وترجع ليه بعدين تكمل التفاصيل.</p>
        <div className="flex flex-col sm:flex-row gap-2">
          <select value={bulkCategory} onChange={e => setBulkCategory(e.target.value)} className="flex-1 px-3 py-2 rounded-lg border border-stone-300 text-sm bg-white">
            <option value="">بدون فئة</option>
            {categories.filter(c => c !== 'all').map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <button onClick={() => fileInputRef.current?.click()} className="bg-[#7C3AED] text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center justify-center gap-1.5">
            <Plus size={16} /> اختار الصور
          </button>
          <input ref={fileInputRef} type="file" accept="image/*" multiple onChange={handleBulkFiles} className="hidden" />
        </div>
      </div>

      {draftCount > 0 && (
        <div className="text-xs text-[#7C3AED] mb-3">📝 عندك {draftCount} منتج(ات) مسودة كتستنى التفاصيل — كمّلهم أسفله.</div>
      )}

      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
        {variants.map(v => <ProductCard key={v.id} variant={v} categories={categories} onSave={onUpdateVariant} />)}
        {!variants.length && <div className="col-span-full text-center text-stone-400 text-sm py-10">لا توجد منتجات بعد — ابدأ برفع صور بالجملة فوق</div>}
      </div>
    </div>
  );
}

// ============== APP SHELL ==============

const NAV_ITEMS = [
  { key: 'dashboard', label: 'الرئيسية', icon: Home, built: true },
  { key: 'orders', label: 'الطلبات', icon: Package, built: true },
  { key: 'clients', label: 'الزبناء', icon: Users, built: true },
  { key: 'products', label: 'المنتجات', icon: PackageSearch, built: true },
  { key: 'purchases', label: 'المشتريات', icon: ShieldCheck, built: true },
  { key: 'shipments', label: 'الشحنات', icon: Truck, built: true },
  { key: 'payments', label: 'الدفعات', icon: CreditCard, built: true, ownerOnly: true },
  { key: 'ledger', label: 'السجل المالي', icon: FileText, built: true, ownerOnly: true },
  { key: 'settings', label: 'الإعدادات', icon: Settings, built: true },
];

// Extracted per Production Upgrade Plan (section 2): all business data + logic lives here now,
// IsmaAdmin below only handles navigation/UI state and rendering. Same state, same handlers,
// same behavior — pure reorganization, verified with esbuild + a full balance check.
function useIsmaData() {
  const [role, setRole] = useState('owner');
  const [toast, setToast] = useState(null);
  const showToast = useCallback((message, tone = 'success') => {
    setToast({ message, tone, key: Date.now() });
  }, []);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 2600);
    return () => clearTimeout(t);
  }, [toast]);
  const [assistantCanPurchase, setAssistantCanPurchase] = useState(false);
  const [loaded, setLoaded] = useState(false);

  const [clients, setClients] = useState([]);
  const [orders, setOrders] = useState([]);
  const [payments, setPayments] = useState([]);
  const [suppliers, setSuppliers] = useState([]);
  const [variants, setVariants] = useState([]);
  const [purchases, setPurchases] = useState([]);
  const [ledger, setLedger] = useState([]);
  const [shipments, setShipments] = useState([]);
  const [auditLog, setAuditLog] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loadError, setLoadError] = useState(false);

  useEffect(() => {
    (async () => {
      const results = await Promise.all([
        loadData('isma_clients', seedClients),
        loadData('isma_orders', seedOrders),
        loadData('isma_payments', seedPayments),
        loadData('isma_suppliers', seedSuppliers),
        loadData('isma_variants', seedProductVariants),
        loadData('isma_purchases', seedPurchases),
        loadData('isma_ledger', seedLedger),
        loadData('isma_shipments', seedShipments),
        loadData('isma_audit_log', []),
        loadData('isma_categories', ['عبايات', 'شيلات', 'مخاوير', 'أطقم مطرزة']),
      ]);
      const [c, o, p, s, v, pu, l, sh, al, cats] = results;
      setClients(c.value); setOrders(o.value); setPayments(p.value);
      setSuppliers(s.value); setVariants(v.value); setPurchases(pu.value); setLedger(l.value);
      setShipments(sh.value); setAuditLog(al.value); setCategories(cats.value);
      // If ANY key failed to load, don't silently proceed as if this were a fresh/empty account —
      // surface it, and keep writes disabled until the user reloads and a clean load succeeds.
      const anyFailed = results.some(r => !r.ok);
      setLoadError(anyFailed);
      setLoaded(true);
    })();
  }, []);

  // Wrapper used by every persistence effect below: shows a visible error toast on failure instead of
  // swallowing it in console.error, so a failed write is never silently mistaken for a successful one.
  const persistedSave = useCallback(async (key, value) => {
    if (loadError) return; // refuse to write over real data while we're unsure the initial load was clean
    const ok = await saveData(key, value);
    if (!ok) showToast('⚠️ فشل حفظ البيانات! تحقق من الاتصال وحاول مرة أخرى', 'error');
  }, [loadError, showToast]);

  useEffect(() => { if (loaded) persistedSave('isma_clients', clients); }, [clients, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_orders', orders); }, [orders, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_payments', payments); }, [payments, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_suppliers', suppliers); }, [suppliers, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_variants', variants); }, [variants, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_purchases', purchases); }, [purchases, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_ledger', ledger); }, [ledger, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_shipments', shipments); }, [shipments, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_audit_log', auditLog); }, [auditLog, loaded]);
  useEffect(() => { if (loaded) persistedSave('isma_categories', categories); }, [categories, loaded]);

  const handleAddCategory = useCallback((cat) => {
    setCategories(prev => prev.includes(cat) ? prev : [...prev, cat]);
    showToast(`تمت إضافة فئة "${cat}"`);
  }, [showToast]);

  const handleRemoveCategory = useCallback((cat) => {
    setCategories(prev => prev.filter(c => c !== cat));
  }, []);

  // Single append point for the entire app — every handler below calls this, never setAuditLog directly.
  const logAudit = useCallback((entries) => {
    setAuditLog(prev => [...prev, ...entries]);
  }, []);

  const handleAdvance = useCallback((orderId, actingRole) => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;
    const n = nextStatus(order);
    if (!n) return;

    if (n === 'closed') {
      if (actingRole !== 'owner') {
        alert('إغلاق الطلب ماليًا متاح فقط لـOwner، لأنه ينشئ قيوداً فـFinancialLedger.');
        return;
      }
      const orderPayments = payments.filter(p => p.salesOrderId === orderId);
      const confirmedPaid = orderPayments.filter(p => p.status === 'confirmed' && p.direction === 'from_client').reduce((s, p) => s + p.amount, 0);
      if (confirmedPaid < order.agreedPrice) {
        alert('لا يمكن إغلاق الطلب: الدفعات المؤكدة لا تغطي كامل السعر المتفق عليه بعد.');
        return;
      }
      if (!order.quantity || order.quantity <= 0) {
        alert('لا يمكن إغلاق الطلب: الكمية غير صالحة (يجب أن تكون أكبر من صفر).');
        return;
      }
      const basis = getCostBasis(order, purchases, variants);
      if (!basis) {
        alert('لا يمكن إغلاق الطلب: يجب ربط الطلب بمنتج مخزون أو بعملية شراء مستلمة أولاً لتحديد التكلفة (Cost Basis)، وأن تكون التكلفة أكبر من صفر.');
        return;
      }
      const today = new Date().toISOString().slice(0, 10);
      // FIXED (Critical Review finding): basis.value is a PER-UNIT cost; agreedPrice is the TOTAL
      // for the whole order quantity. Multiplying by quantity is required for correctness.
      const marginAmount = Math.round((order.agreedPrice - (basis.value * order.quantity)) * 100) / 100;
      const fxAmount = computeFXDifference(order, orderPayments);

      const newEntries = [{
        id: Date.now(), type: 'هامش_منتج', amount: marginAmount, currency: order.currency, salesOrderId: order.id, purchaseId: null,
        costBasisTypeUsed: basis.type, costValueUsed: basis.value, reversedEntryId: null, status: 'نهائي', createdAt: today,
      }];
      // FX difference is only recorded as its own entry when non-zero — keeps the ledger clean while every
      // currency conversion still happens per-payment per ج.5, ready to surface real amounts once multi-currency payments occur.
      if (fxAmount !== 0) {
        newEntries.push({
          id: Date.now() + 1, type: 'فرق_صرف', amount: fxAmount, currency: order.currency, salesOrderId: order.id, purchaseId: null,
          costBasisTypeUsed: null, costValueUsed: null, reversedEntryId: null, status: 'نهائي', createdAt: today,
        });
      }
      // Shipping Cost / Shipping Transaction entries are intentionally NOT created in this phase:
      // the Shipments module (Phase 4) is still pending, so there is no shipping-cost source to record yet.
      // Per ج.5/ج.2, this entry type only ever fires when money actually moves through ISMA for shipping.
      setLedger(prev => [...prev, ...newEntries]);
      logAudit(newEntries.map(e => makeAuditEntry(actingRole, 'FinancialLedger', e.id, 'created', null, `${e.type}: ${e.amount}`)));

      // Stock decrement — the symmetric counterpart to applyReceivedCostUpdate's increment.
      // Whichever variant actually backed the cost basis (specific → the linked purchase's variant,
      // average → the order's linked variant) loses `quantity` units from the pooled counter now,
      // at closing, matching the same moment the cost is frozen — not earlier, not never.
      const consumedVariantId = basis.type === 'specific'
        ? purchases.find(p => p.linkedSalesOrderId === order.id && p.status === 'received')?.productVariantId
        : order.productVariantId;
      if (consumedVariantId) {
        setVariants(prev => prev.map(v => v.id === consumedVariantId ? { ...v, stockQuantity: v.stockQuantity - order.quantity } : v));
      }
      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: n } : o));
      logAudit([makeAuditEntry(actingRole, 'SalesOrder', orderId, 'status', order.status, n)]);
      showToast(`تم إغلاق الطلب ماليًا — الهامش: ${marginAmount} ${order.currency}`, 'success');
      return;
    }

    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: n } : o));
    logAudit([makeAuditEntry(actingRole, 'SalesOrder', orderId, 'status', order.status, n)]);
    showToast(`تقدَّم الطلب إلى: ${STATUS_LABELS[n]}`);
  }, [orders, payments, purchases, variants, logAudit, showToast]);

  const handleAddPayment = useCallback((orderId, amount, status) => {
    const order = orders.find(o => o.id === orderId);
    setPayments(prev => [...prev, {
      id: Date.now(), salesOrderId: orderId, purchaseId: null, direction: 'from_client',
      amount, currency: order?.currency || 'AED', fxRateAtPayment: 1, status,
      date: new Date().toISOString().slice(0, 10),
    }]);
    showToast(`تم تسجيل دفعة ${amount} ${order?.currency || 'AED'}`);
  }, [orders, showToast]);

  const handleAddSupplierPayment = useCallback((purchaseId, amount, status, currency, actingRole) => {
    if (actingRole !== 'owner') {
      alert('تسجيل دفعات للمورد متاح فقط لـOwner (بيانات مالية/تجارية).');
      return;
    }
    const id = Date.now();
    setPayments(prev => [...prev, {
      id, salesOrderId: null, purchaseId, direction: 'to_supplier',
      amount, currency, fxRateAtPayment: 1, status,
      date: new Date().toISOString().slice(0, 10),
    }]);
    logAudit([makeAuditEntry(actingRole, 'Payment', id, 'created', null, `to_supplier: ${amount} ${currency}, status=${status}`)]);
    showToast(`تم تسجيل دفعة ${amount} ${currency} للمورد`);
  }, [logAudit, showToast]);

  const handleLinkVariant = useCallback((orderId, variantId) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, productVariantId: variantId } : o));
  }, []);

  const handleCreateShipment = useCallback((orderId, partner, actingRole) => {
    const id = Date.now();
    setShipments(prev => [...prev, {
      id, salesOrderId: orderId, partner: partner || 'Mozouna Group', trackingNumber: '',
      sentDate: new Date().toISOString().slice(0, 10), expectedDate: '', deliveredDate: null,
      status: 'preparing', coveredQuantity: null,
    }]);
    logAudit([makeAuditEntry(actingRole, 'Shipment', id, 'created', null, `salesOrderId=${orderId}`)]);
    showToast('تم إنشاء شحنة جديدة');
    return id;
  }, [logAudit, showToast]);

  const handleUpdateShipmentStatus = useCallback((shipmentId, newStatus, actingRole) => {
    setShipments(prev => {
      const shipment = prev.find(s => s.id === shipmentId);
      const oldStatus = shipment?.status;
      logAudit([makeAuditEntry(actingRole, 'Shipment', shipmentId, 'status', oldStatus, newStatus)]);
      return prev.map(s => s.id === shipmentId
        ? { ...s, status: newStatus, deliveredDate: newStatus === 'delivered' ? new Date().toISOString().slice(0, 10) : s.deliveredDate }
        : s);
    });
  }, [logAudit]);

  // Shipping Cost / Shipping Transaction entries only ever get created here, from an explicit Owner
  // action, and only when shipping_arrangement = handled_by_isma (enforced in ShipmentDetail's UI gate).
  // The Shipment record itself never stores this amount — only the ledger does (ج.2 / ج.5).
  const handleRecordShippingLedgerEntry = useCallback((shipmentId, orderId, amount, actingRole, currency) => {
    if (actingRole !== 'owner') {
      alert('تسجيل قيد شحن مالي متاح فقط لـOwner (يكتب مباشرة فـFinancialLedger).');
      return;
    }
    const id = Date.now();
    setLedger(prev => [...prev, {
      id, type: 'Shipping Cost / Shipping Transaction', amount, currency: currency || 'AED', salesOrderId: orderId,
      purchaseId: null, shipmentId, costBasisTypeUsed: null, costValueUsed: null,
      reversedEntryId: null, status: 'نهائي', createdAt: new Date().toISOString().slice(0, 10),
    }]);
    logAudit([makeAuditEntry(actingRole, 'FinancialLedger', id, 'created', null, `Shipping Cost / Shipping Transaction: ${amount}`)]);
  }, [logAudit]);

  const handleUpdateNotes = useCallback((orderId, notes) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, notes } : o));
  }, []);

  const handleUpdateClientNotes = useCallback((clientId, notes) => {
    setClients(prev => prev.map(c => c.id === clientId ? { ...c, notes } : c));
  }, []);

  const handleCreateClient = useCallback((data) => {
    if (data.phone && clients.some(c => c.phone === data.phone)) {
      alert(`زبون بنفس رقم الهاتف (${data.phone}) موجود أصلاً — تجنّباً للتكرار، افتح ملفه الموجود بدل إنشاء واحد جديد.`);
      return;
    }
    const id = Date.now();
    setClients(prev => [...prev, { id, name: data.name, phone: data.phone || '', city: data.city || '', status: 'active', notes: '' }]);
    logAudit([makeAuditEntry(role, 'Client', id, 'created', null, data.name)]);
    showToast(`تمت إضافة الزبون "${data.name}"`);
  }, [role, logAudit, showToast, clients]);

  const handleCreateOrder = useCallback((data) => {
    const id = Date.now();
    setOrders(prev => [...prev, {
      id, clientId: data.clientId, productName: data.productName, productVariantId: data.productVariantId,
      quantity: data.quantity, agreedPrice: data.agreedPrice, currency: data.currency, fxRateAtAgreement: 1,
      originType: data.originType, shippingArrangement: data.shippingArrangement, status: 'agreed',
      notes: '', createdAt: new Date().toISOString().slice(0, 10),
    }]);
    logAudit([makeAuditEntry(role, 'SalesOrder', id, 'created', null, `${data.productName} — ${data.agreedPrice} ${data.currency}`)]);
    showToast('تم إنشاء الطلب بحالة "تم الاتفاق"');
  }, [role, logAudit, showToast]);

  const handleCreateSupplier = useCallback((data) => {
    const id = Date.now();
    setSuppliers(prev => [...prev, { id, name: data.name, location: data.location || '', contactInfo: data.contactInfo || '', reliabilityNote: '' }]);
    logAudit([makeAuditEntry(role, 'Supplier', id, 'created', null, data.name)]);
    showToast(`تمت إضافة المورد "${data.name}"`);
    return id;
  }, [role, logAudit, showToast]);

  const handleCreateVariant = useCallback((data) => {
    const id = Date.now();
    setVariants(prev => [...prev, { id, name: data.name, category: data.category || '', stockQuantity: 0, averageInventoryCost: 0, sellingPrice: data.sellingPrice || 0, currency: data.currency || 'AED', images: data.images || [] }]);
    logAudit([makeAuditEntry(role, 'ProductVariant', id, 'created', null, data.name)]);
    showToast(`تمت إضافة المنتج "${data.name}"`);
    return id;
  }, [role, logAudit, showToast]);

  const handleUpdateVariant = useCallback((id, patch) => {
    setVariants(prev => prev.map(v => v.id === id ? { ...v, ...patch } : v));
    logAudit([makeAuditEntry(role, 'ProductVariant', id, 'updated', null, patch.name || '')]);
    showToast('تم تحديث المنتج');
  }, [role, logAudit, showToast]);

  const handleCreatePurchase = useCallback((data, actingRole, actingCanPurchase) => {
    if (!(actingRole === 'owner' || (actingRole === 'assistant' && actingCanPurchase))) {
      alert('إنشاء عملية شراء يتطلب صلاحية can_execute_purchase.');
      return;
    }
    const id = Date.now();
    const today = new Date().toISOString().slice(0, 10);
    const newPurchase = {
      id, supplierId: data.supplierId, productVariantId: data.variantId, quantity: data.quantity,
      unitCost: data.unitCost, currency: data.currency, fxRateAtPurchase: 1, date: today,
      status: data.status, linkedSalesOrderId: data.linkedOrderId ? Number(data.linkedOrderId) : null,
      history: [{ event: data.status === 'received' ? 'تم إنشاء الشراء وتسجيله كمُستلَم' : 'تم إنشاء الشراء — بانتظار الاستلام', timestamp: today }],
    };
    setPurchases(prev => [...prev, newPurchase]);
    logAudit([makeAuditEntry(actingRole, 'Purchase', id, 'created', null, `${data.quantity}x @ ${data.unitCost} ${data.currency}, status=${data.status}`)]);
    if (data.status === 'received') {
      setVariants(prev => prev.map(v => v.id === data.variantId ? applyReceivedCostUpdate(v, newPurchase) : v));
      setPurchases(prev => prev.map(p => p.id === id ? { ...p, history: [...p.history, { event: 'تحديث تلقائي للمخزون والمتوسط المتحرك', timestamp: today }] } : p));
      logAudit([makeAuditEntry(actingRole, 'ProductVariant', data.variantId, 'average_inventory_cost/stock_quantity', null, 'تحديث تلقائي عند الاستلام')]);
    }
    showToast('تم تسجيل الشراء بنجاح');
  }, [logAudit, showToast]);

  const handleMarkReceived = useCallback((purchaseId, actingRole, actingCanPurchase) => {
    if (!(actingRole === 'owner' || (actingRole === 'assistant' && actingCanPurchase))) {
      alert('تأكيد الاستلام يتطلب صلاحية can_execute_purchase.');
      return;
    }
    const today = new Date().toISOString().slice(0, 10);
    setPurchases(prev => {
      const purchase = prev.find(p => p.id === purchaseId);
      if (!purchase || purchase.status === 'received') return prev;
      setVariants(vPrev => vPrev.map(v => v.id === purchase.productVariantId ? applyReceivedCostUpdate(v, purchase) : v));
      logAudit([
        makeAuditEntry(actingRole, 'Purchase', purchaseId, 'status', 'pending', 'received'),
        makeAuditEntry(actingRole, 'ProductVariant', purchase.productVariantId, 'average_inventory_cost/stock_quantity', null, 'تحديث تلقائي عند الاستلام'),
      ]);
      return prev.map(p => p.id === purchaseId
        ? { ...p, status: 'received', history: [...p.history, { event: 'تم تأكيد الاستلام — تحديث المخزون والمتوسط المتحرك', timestamp: today }] }
        : p);
    });
    showToast('تم تأكيد الاستلام — تحديث المخزون والتكلفة تلقائياً');
  }, [logAudit, showToast]);

  return {
    clients, orders, payments, suppliers, variants, purchases, ledger, shipments, auditLog, categories,
    setClients, setOrders,
    loaded, loadError, role, setRole, assistantCanPurchase, setAssistantCanPurchase, toast,
    handleAddCategory, handleRemoveCategory, handleAdvance, handleAddPayment, handleAddSupplierPayment,
    handleLinkVariant, handleCreateShipment, handleUpdateShipmentStatus, handleRecordShippingLedgerEntry,
    handleUpdateClientNotes, handleUpdateNotes, handleCreateClient, handleCreateOrder, handleCreateSupplier,
    handleCreateVariant, handleUpdateVariant, handleCreatePurchase, handleMarkReceived,
  };
}

// ============== Real Login Screen — authenticates against the actual Supabase project ==============
function LoginScreen({ onSignedIn }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  const handleSubmit = async () => {
    setError(''); setBusy(true);
    try {
      const session = await supabaseSignIn(email.trim(), password);
      onSignedIn(session);
    } catch (e) {
      setError(e.message || 'فشل تسجيل الدخول — تحقق من البريد وكلمة السر');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F7F2E7] p-4 pt-12 pb-20" dir="rtl">
      <div className="bg-white rounded-2xl border border-stone-200 p-6 w-full max-w-sm shadow-lg">
        <div className="w-14 h-14 rounded-full border-2 border-[#D97706] mx-auto mb-4 flex items-center justify-center">
          <img src={ISMA_LOGO} alt="ISMA" className="w-9 h-9 object-contain" />
        </div>
        <h2 className="font-display text-xl text-center text-[#153630] mb-1">تسجيل الدخول</h2>
        <p className="text-xs text-stone-500 text-center mb-5">دخول حقيقي — متصل بقاعدة البيانات الفعلية</p>
        <div className="space-y-3">
          <input value={email} onChange={e => setEmail(e.target.value)} placeholder="البريد الإلكتروني" type="email"
            className="w-full px-3 py-2.5 rounded-lg border border-stone-300 text-sm focus:border-[#D97706] focus:outline-none" />
          <input value={password} onChange={e => setPassword(e.target.value)} placeholder="كلمة السر" type="password"
            onKeyDown={e => e.key === 'Enter' && handleSubmit()}
            className="w-full px-3 py-2.5 rounded-lg border border-stone-300 text-sm focus:border-[#D97706] focus:outline-none" />
        </div>
        {error && <div className="text-xs text-[#DC2626] mt-3 text-center">{error}</div>}
        <button onClick={handleSubmit} disabled={busy || !email || !password}
          className="w-full mt-4 bg-[#153630] text-white py-2.5 rounded-lg text-sm font-medium disabled:opacity-50">
          {busy ? 'جاري الدخول...' : 'دخول'}
        </button>
      </div>
    </div>
  );
}

export default function IsmaAdmin() {
  const [appMode, setAppMode] = useState(() =>
    typeof window !== 'undefined' && window.location.pathname.replace(/\/+$/, '') === '/catalog'
      ? 'customer'
      : 'admin'
  );
  const [view, setView] = useState({ name: 'dashboard' });
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [session, setSession] = useState(null);
  const {
    clients, orders, payments, suppliers, variants, purchases, ledger, shipments, auditLog, categories,
    setClients, setOrders,
    loaded, loadError, role, setRole, assistantCanPurchase, setAssistantCanPurchase, toast,
    handleAddCategory, handleRemoveCategory, handleAdvance, handleAddPayment, handleAddSupplierPayment,
    handleLinkVariant, handleCreateShipment, handleUpdateShipmentStatus, handleRecordShippingLedgerEntry,
    handleUpdateClientNotes, handleUpdateNotes, handleCreateClient, handleCreateOrder, handleCreateSupplier,
    handleCreateVariant, handleUpdateVariant, handleCreatePurchase, handleMarkReceived,
  } = useIsmaData();

  if (!loaded) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-3 bg-[#F7F2E7]">
        <img src={ISMA_LOGO} alt="ISMA" className="w-10 h-10 object-contain animate-pulse" />
        <div className="font-display text-[#153630]/60 text-sm" style={{ fontFamily: "'Tajawal', sans-serif" }}>جاري التحميل...</div>
      </div>
    );
  }

  if (appMode === 'admin' && !session) {
    return <LoginScreen onSignedIn={setSession} />;
  }

  if (appMode === 'customer') {
    return (
      <CustomerCatalog variants={variants} clients={clients} orders={orders}
        setClients={setClients} setOrders={setOrders}
        onSwitchToAdmin={() => setAppMode('admin')} />
    );
  }

  const activeOrder = view.name === 'order-detail' ? orders.find(o => o.id === view.id) : null;
  const activeClientProfile = view.name === 'client-detail' ? clients.find(c => c.id === view.id) : null;
  const activePurchase = view.name === 'purchase-detail' ? purchases.find(p => p.id === view.id) : null;
  const activeShipment = view.name === 'shipment-detail' ? shipments.find(s => s.id === view.id) : null;
  const activeClient = activeOrder ? clients.find(c => c.id === activeOrder.clientId) : null;

  return (
    <div dir="rtl" className="min-h-screen bg-[#F7F2E7] flex" style={{ fontFamily: "'Tajawal', 'Inter', sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@300;400;500;700;800&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600&display=swap');
        .font-display { font-family: 'Fraunces', Georgia, serif; }
        ::selection { background: #FBBF24; color: #153630; }
        .isma-card { box-shadow: 0 1px 2px rgba(21,54,48,0.04), 0 2px 8px rgba(21,54,48,0.06); }
        .isma-card:hover { box-shadow: 0 2px 4px rgba(21,54,48,0.06), 0 6px 16px rgba(21,54,48,0.08); }
        .isma-sidebar { position: fixed; top: 0; bottom: 0; right: 0; transform: translateX(100%); transition: transform 0.3s ease-out; }
        .isma-sidebar.open { transform: translateX(0); }
        @media (min-width: 1024px) {
          .isma-sidebar { position: static; transform: none !important; box-shadow: none; }
        }
        @keyframes isma-toast-in { from { transform: translateY(12px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
        .isma-toast { animation: isma-toast-in 0.25s ease-out; }
      `}</style>
      {/* Sidebar */}
      <div className={`isma-sidebar ${sidebarOpen ? 'open' : ''} z-40 w-64 text-[#F7F2E7] p-5 flex flex-col shadow-2xl`} style={{ background: 'linear-gradient(160deg, #0D9488, #0F766E 45%, #134E4A 100%)' }}>
        <div className="flex items-center gap-2.5 mb-1">
          <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center overflow-hidden shrink-0 shadow-sm">
            <img src={ISMA_LOGO} alt="ISMA" className="w-full h-full object-contain p-1" />
          </div>
          <div className="font-display text-xl tracking-wide">ISMA</div>
        </div>
        <div className="text-xs text-[#FBBF24]/90 mb-7 tracking-wide">لوحة التحكم الداخلية</div>

        <nav className="space-y-1 flex-1">
          {NAV_ITEMS.filter(n => !n.ownerOnly || role === 'owner').map(n => {
            const Icon = n.icon;
            const active = view.name === n.key
              || (view.name === 'order-detail' && n.key === 'orders')
              || (view.name === 'client-detail' && n.key === 'clients')
              || (view.name === 'purchase-detail' && n.key === 'purchases')
              || (view.name === 'shipment-detail' && n.key === 'shipments');
            const restrictedByPermission = n.key === 'purchases' && role === 'assistant' && !assistantCanPurchase;
            const usable = n.built && !restrictedByPermission;
            const mc = MODULE_COLORS[n.key] || '#FBBF24';
            return (
              <button key={n.key} disabled={!usable}
                onClick={() => { if (usable) { setView({ name: n.key }); setSidebarOpen(false); } }}
                style={active ? { backgroundColor: `${mc}35`, borderInlineStart: `3px solid ${mc}` } : { borderInlineStart: '3px solid transparent' }}
                className={`w-full flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-sm transition-all duration-150 ${active ? 'text-white shadow-sm' : usable ? 'text-white/70 hover:bg-white/[0.07] hover:text-white' : 'text-white/25 cursor-not-allowed'}`}>
                <Icon size={16} style={active ? { color: '#F7F2E7' } : undefined} />
                {n.label}
                {!n.built && <span className="text-[10px] ms-auto">قريباً</span>}
                {n.built && restrictedByPermission && <span className="text-[10px] ms-auto flex items-center gap-1"><Lock size={10} /> بدون صلاحية</span>}
              </button>
            );
          })}
        </nav>

        <div className="pt-4 border-t border-white/10">
          <div className="text-[10px] text-white/40 mb-2">وضع العرض (تجريبي)</div>
          <div className="flex gap-1 bg-white/5 rounded-lg p-1">
            <button onClick={() => setRole('owner')} className={`flex-1 flex items-center justify-center gap-1 py-1.5 rounded-md text-xs ${role === 'owner' ? 'bg-white text-[#153630]' : 'text-white/60'}`}>
              <ShieldCheck size={12} /> Owner
            </button>
            <button onClick={() => setRole('assistant')} className={`flex-1 flex items-center justify-center gap-1 py-1.5 rounded-md text-xs ${role === 'assistant' ? 'bg-white text-[#153630]' : 'text-white/60'}`}>
              <UserCog size={12} /> Assistant
            </button>
          </div>
          {role === 'assistant' && (
            <label className="flex items-center gap-2 mt-2 text-[11px] text-white/60 px-1 cursor-pointer">
              <input type="checkbox" checked={assistantCanPurchase} onChange={e => {
                logAudit([makeAuditEntry('owner', 'User', 'assistant', 'can_execute_purchase', assistantCanPurchase, e.target.checked)]);
                setAssistantCanPurchase(e.target.checked);
              }} />
              صلاحية can_execute_purchase
            </label>
          )}
          <button onClick={() => setAppMode('customer')} className="w-full flex items-center justify-center gap-1.5 mt-3 text-[11px] text-[#FBBF24] border border-[#FBBF24]/30 rounded-lg py-1.5 hover:bg-white/5 transition-colors">
            <Store size={12} /> معاينة الكاتالوج (كزبون)
          </button>
        </div>
      </div>

      {sidebarOpen && <div className="fixed inset-0 bg-black/30 z-30 lg:hidden" onClick={() => setSidebarOpen(false)} />}

      {/* Main */}
      <div className="flex-1 min-w-0">
        {loadError && (
          <div className="bg-[#DC2626] text-white text-sm px-4 py-2.5 flex items-center gap-2 sticky top-0 z-40">
            <AlertTriangle size={16} className="shrink-0" />
            <span>⚠️ تعذّر تحميل بعض البيانات بشكل مؤكَّد — أعِد تحميل الصفحة قبل إجراء أي تعديل، لتفادي فقدان بيانات حقيقية.</span>
          </div>
        )}
        <div className="lg:hidden flex items-center justify-between px-4 py-3 bg-[#FDF8ED]/90 backdrop-blur border-b border-stone-200 sticky top-0 z-20">
          <button onClick={() => setSidebarOpen(true)} className="p-1 -m-1"><Menu size={22} className="text-[#153630]" /></button>
          <div className="flex items-center gap-2">
            <img src={ISMA_LOGO} alt="ISMA" className="w-6 h-6 object-contain" />
            <div className="font-display text-lg text-[#153630]">ISMA</div>
          </div>
          <div className="w-6" />
        </div>

        <div className="p-4 sm:p-6 lg:p-8">
          {(() => {
            const VIEW_META = {
              dashboard: { label: 'نظرة عامة', module: 'dashboard', Icon: Home },
              orders: { label: 'الطلبات', module: 'orders', Icon: Package },
              'order-detail': { label: 'تفاصيل الطلب', module: 'orders', Icon: Package },
              clients: { label: 'الزبناء', module: 'clients', Icon: Users },
              'client-detail': { label: 'ملف الزبون', module: 'clients', Icon: Users },
              products: { label: 'المنتجات', module: 'products', Icon: PackageSearch },
              purchases: { label: 'المشتريات', module: 'purchases', Icon: Receipt },
              'purchase-detail': { label: 'تفاصيل الشراء', module: 'purchases', Icon: Receipt },
              payments: { label: 'الدفعات', module: 'orders', Icon: CreditCard },
              settings: { label: 'الإعدادات', module: 'dashboard', Icon: Settings },
              ledger: { label: 'السجل المالي', module: 'ledger', Icon: Wallet },
              shipments: { label: 'الشحنات', module: 'shipments', Icon: Truck },
              'shipment-detail': { label: 'تفاصيل الشحنة', module: 'shipments', Icon: Truck },
            };
            const meta = VIEW_META[view.name] || VIEW_META.dashboard;
            const mc = MODULE_COLORS[meta.module];
            const MetaIcon = meta.Icon;
            return (
              <div className="mb-6 flex items-center gap-3">
                <div className="w-11 h-11 rounded-2xl flex items-center justify-center shrink-0 shadow-sm" style={{ background: `linear-gradient(135deg, ${mc}, ${mc}CC)` }}>
                  <MetaIcon size={20} className="text-white" strokeWidth={2} />
                </div>
                <h1 className="font-display text-2xl tracking-tight" style={{ color: mc }}>{meta.label}</h1>
              </div>
            );
          })()}

          {view.name === 'dashboard' && <Dashboard orders={orders} clients={clients} payments={payments} purchases={purchases} variants={variants} ledger={ledger} role={role} setView={setView} />}
          {view.name === 'orders' && <OrdersList orders={orders} clients={clients} payments={payments} role={role} setView={setView} onQuickAdvance={handleAdvance} onCreateOrder={handleCreateOrder} variants={variants} />}
          {view.name === 'order-detail' && activeOrder && (
            <OrderDetail order={activeOrder} client={activeClient} payments={payments} purchases={purchases} variants={variants} ledger={ledger} shipments={shipments} role={role}
              onBack={() => setView({ name: 'orders' })} onAdvance={handleAdvance}
              onAddPayment={handleAddPayment} onUpdateNotes={handleUpdateNotes} onLinkVariant={handleLinkVariant}
              onOpenClient={(clientId) => setView({ name: 'client-detail', id: clientId })}
              onCreateShipment={(orderId, partner, actingRole) => { const id = handleCreateShipment(orderId, partner, actingRole); setView({ name: 'shipment-detail', id }); }}
              setView={setView} />
          )}
          {view.name === 'clients' && <ClientsList clients={clients} orders={orders} ledger={ledger} setView={setView} onCreateClient={handleCreateClient} />}
          {view.name === 'client-detail' && activeClientProfile && (
            <ClientDetail client={activeClientProfile} orders={orders} ledger={ledger} role={role}
              onBack={() => setView({ name: 'clients' })} setView={setView}
              onUpdateNotes={handleUpdateClientNotes} />
          )}
          {view.name === 'products' && (
            <ProductsManager variants={variants} categories={categories} onCreateVariant={handleCreateVariant} onUpdateVariant={handleUpdateVariant} />
          )}
          {view.name === 'purchases' && (
            <PurchasesList purchases={purchases} suppliers={suppliers} variants={variants} categories={categories} salesOrders={orders}
              role={role} assistantCanPurchase={assistantCanPurchase} setView={setView}
              onCreatePurchase={handleCreatePurchase} onCreateSupplier={handleCreateSupplier} onCreateVariant={handleCreateVariant} />
          )}
          {view.name === 'purchase-detail' && activePurchase && (
            <PurchaseDetail purchase={activePurchase}
              supplier={suppliers.find(s => s.id === activePurchase.supplierId)}
              variant={variants.find(v => v.id === activePurchase.productVariantId)}
              linkedOrder={orders.find(o => o.id === activePurchase.linkedSalesOrderId)}
              payments={payments}
              role={role} assistantCanPurchase={assistantCanPurchase}
              onBack={() => setView({ name: 'purchases' })} onMarkReceived={handleMarkReceived}
              onAddSupplierPayment={handleAddSupplierPayment} />
          )}
          {view.name === 'shipments' && (
            <ShipmentsList shipments={shipments} orders={orders} clients={clients} setView={setView} />
          )}
          {view.name === 'shipment-detail' && activeShipment && (
            <ShipmentDetail shipment={activeShipment}
              order={orders.find(o => o.id === activeShipment.salesOrderId)}
              client={clients.find(c => c.id === orders.find(o => o.id === activeShipment.salesOrderId)?.clientId)}
              role={role} onBack={() => setView({ name: 'shipments' })}
              onUpdateStatus={handleUpdateShipmentStatus}
              onRecordShippingLedgerEntry={handleRecordShippingLedgerEntry} />
          )}
          {view.name === 'settings' && (
            <SettingsView categories={categories} onAddCategory={handleAddCategory} onRemoveCategory={handleRemoveCategory}
              variants={variants} role={role} assistantCanPurchase={assistantCanPurchase} />
          )}
          {view.name === 'payments' && role === 'owner' && (
            <PaymentsView payments={payments} orders={orders} purchases={purchases} clients={clients} suppliers={suppliers} role={role} />
          )}
          {view.name === 'ledger' && role === 'owner' && (
            <FinancialLedgerView ledger={ledger} orders={orders} clients={clients} />
          )}
        </div>
      </div>

      {toast && (
        <div key={toast.key} className="isma-toast fixed bottom-5 inset-x-0 flex justify-center z-50 px-4 pointer-events-none">
          <div className={`flex items-center gap-2 text-white text-sm px-4 py-3 rounded-xl shadow-2xl pointer-events-auto max-w-sm ${toast.tone === 'error' ? 'bg-[#DC2626]' : 'bg-[#0D9488]'}`}>
            {toast.tone === 'error' ? <AlertTriangle size={16} className="shrink-0" /> : <CheckCircle2 size={16} className="text-[#7FCBA4] shrink-0" />}
            <span>{toast.message}</span>
          </div>
        </div>
      )}
    </div>
  );
}
